import{_ as a,o as r,c as o,a0 as l}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"常見問題","description":"","frontmatter":{},"headers":[],"relativePath":"zh_TW/guide/faq.md","filePath":"zh_TW/guide/faq.md"}'),t={name:"zh_TW/guide/faq.md"};function n(s,e,d,i,h,u){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><h2 id="kernelsu-是否支援我的裝置" tabindex="-1">KernelSU 是否支援我的裝置？ <a class="header-anchor" href="#kernelsu-是否支援我的裝置" aria-label="Permalink to &quot;KernelSU 是否支援我的裝置？&quot;">​</a></h2><p>首先，您的裝置應該能解鎖 Bootloader。如果不能，則不支援。</p><p>然後在您的裝置上安裝 KernelSU 管理員並開啟它，如果它顯示 <code>不支援</code>，那麼您的裝置沒有官方支援的開箱即用的 Boot 映像；但您可以自行建置核心來源並整合 KernelSU 以繼續使用。</p><h2 id="kernelsu-是否需要解鎖-bootloader" tabindex="-1">KernelSU 是否需要解鎖 Bootloader？ <a class="header-anchor" href="#kernelsu-是否需要解鎖-bootloader" aria-label="Permalink to &quot;KernelSU 是否需要解鎖 Bootloader？&quot;">​</a></h2><p>當然需要。</p><h2 id="kernelsu-是否支援模組" tabindex="-1">KernelSU 是否支援模組？ <a class="header-anchor" href="#kernelsu-是否支援模組" aria-label="Permalink to &quot;KernelSU 是否支援模組？&quot;">​</a></h2><p>支援，大多數 Magisk 模組都可以在 KernelSU 上運作。但是，如果您的模組需要修改 <code>/system</code> 檔案，您需要安裝 <a href="./metamodule.html">metamodule</a>(如 <code>meta-overlayfs</code>)。其他模組功能無需 metamodule 即可運作。請參閱 <a href="./module.html">模組指南</a> 以獲取更多資訊。</p><h2 id="kernelsu-是否支援-xposed" tabindex="-1">KernelSU 是否支援 Xposed ？ <a class="header-anchor" href="#kernelsu-是否支援-xposed" aria-label="Permalink to &quot;KernelSU 是否支援 Xposed ？&quot;">​</a></h2><p>支援。<a href="https://github.com/canyie/Dreamland" target="_blank" rel="noreferrer">Dreamland</a> 和 <a href="https://taichi.cool" target="_blank" rel="noreferrer">TaiChi</a> 可以正常運作。LSPosed 可以在 <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> 的支援下正常運作。</p><h2 id="kernelsu-支援-zygisk-嗎" tabindex="-1">KernelSU 支援 Zygisk 嗎？ <a class="header-anchor" href="#kernelsu-支援-zygisk-嗎" aria-label="Permalink to &quot;KernelSU 支援 Zygisk 嗎？&quot;">​</a></h2><p>KernelSU 沒有內建 Zygisk 支援，但是您可以用 <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> 來使用 Zygisk 模組。</p><h2 id="kernelsu-與-magisk-相容嗎" tabindex="-1">KernelSU 與 Magisk 相容嗎？ <a class="header-anchor" href="#kernelsu-與-magisk-相容嗎" aria-label="Permalink to &quot;KernelSU 與 Magisk 相容嗎？&quot;">​</a></h2><p>KernelSU 的模組系統與 Magisk 的 magic mount 存在衝突，如果在 KernelSU 中啟用了任何模組，那麼整個 Magisk 將無法正常運作。</p><p>但是如果您只使用 KernelSU 的 <code>su</code>，那么它會和 Magisk 一同運作：KernelSU 修改 <code>kernel</code>、Magisk 修改 <code>ramdisk</code>，它們可以搭配使用。</p><h2 id="kernelsu-会取代-magisk-嗎" tabindex="-1">KernelSU 会取代 Magisk 嗎？ <a class="header-anchor" href="#kernelsu-会取代-magisk-嗎" aria-label="Permalink to &quot;KernelSU 会取代 Magisk 嗎？&quot;">​</a></h2><p>我們不這樣認為，這也不是我們的目標。Magisk 對於使用者空間 Root 解決方案來說已經足夠優秀了，它會存在很長一段時間。KernelSU 的目標是為使用者提供核心介面，而非取代 Magisk。</p><h2 id="kernelsu-可以支援非-gki-裝置嗎" tabindex="-1">KernelSU 可以支援非 GKI 裝置嗎？ <a class="header-anchor" href="#kernelsu-可以支援非-gki-裝置嗎" aria-label="Permalink to &quot;KernelSU 可以支援非 GKI 裝置嗎？&quot;">​</a></h2><p>可以。但是您應該下載核心來源並整合 KernelSU 至來源樹狀結構並自行編譯核心。</p><h2 id="kernelsu-支援-android-12-以下的裝置嗎" tabindex="-1">KernelSU 支援 Android 12 以下的裝置嗎？ <a class="header-anchor" href="#kernelsu-支援-android-12-以下的裝置嗎" aria-label="Permalink to &quot;KernelSU 支援 Android 12 以下的裝置嗎？&quot;">​</a></h2><p>影響 KernelSU 相容性的是裝置的核心版本，它與 Android 版本並無直接關係。唯一有關聯的是：<strong>原廠</strong> Android 12 的裝置，一定是 5.10 或更高的核心 (GKI 裝置)；因此結論如下：</p><ol><li>原廠 Android 12 的裝置必定支援 (GKI 裝置)</li><li>舊版核心的裝置 (即使是 Android 12，也可能是舊版核心) 是相容的 (您需要自行建置核心)</li></ol><h2 id="kernelsu-可以支援舊版核心嗎" tabindex="-1">KernelSU 可以支援舊版核心嗎？ <a class="header-anchor" href="#kernelsu-可以支援舊版核心嗎" aria-label="Permalink to &quot;KernelSU 可以支援舊版核心嗎？&quot;">​</a></h2><p>可以，目前最低支援到 4.14；更低的版本您需要手動移植它，歡迎 PR！</p><h2 id="如何為舊版核心整合-kernelsu" tabindex="-1">如何為舊版核心整合 KernelSU？ <a class="header-anchor" href="#如何為舊版核心整合-kernelsu" aria-label="Permalink to &quot;如何為舊版核心整合 KernelSU？&quot;">​</a></h2><p>請參閱<a href="./how-to-integrate-for-non-gki.html">指南</a></p><h2 id="為何我的-android-版本為-13-但核心版本卻是-android12-5-10" tabindex="-1">為何我的 Android 版本為 13，但核心版本卻是 &quot;android12-5.10&quot;？ <a class="header-anchor" href="#為何我的-android-版本為-13-但核心版本卻是-android12-5-10" aria-label="Permalink to &quot;為何我的 Android 版本為 13，但核心版本卻是 &quot;android12-5.10&quot;？&quot;">​</a></h2><p>核心版本與 Android 版本無關，如果您要使用 KernelSU，請一律使用<strong>核心版本</strong>而非 Android 版本，如果你為 &quot;android12-5.10&quot; 的裝置寫入 Android 13 的核心，等候您的將會是開機迴圈。</p><h2 id="我是-gki1-0-能用-kernelsu-嗎" tabindex="-1">我是 GKI1.0，能用 KernelSU 嗎？ <a class="header-anchor" href="#我是-gki1-0-能用-kernelsu-嗎" aria-label="Permalink to &quot;我是 GKI1.0，能用 KernelSU 嗎？&quot;">​</a></h2><p>GKI1 與 GKI2 完全不同，所以您需要自行編譯核心。</p><h2 id="kernelsu-支援-mount-master-全域掛接命名空間嗎" tabindex="-1">KernelSU 支援 --mount-master/全域掛接命名空間嗎？ <a class="header-anchor" href="#kernelsu-支援-mount-master-全域掛接命名空間嗎" aria-label="Permalink to &quot;KernelSU 支援 --mount-master/全域掛接命名空間嗎？&quot;">​</a></h2><p>目前沒有 (未來可能會支援)，但實際上有很多種方法手動進入全域命名空間，無需 <code>su</code> 內建支援，比如：</p><ol><li><code>nsenter -t 1 -m sh</code> 可以取得一個全域 mount namespace 的 shell.</li><li>在您要執行的命令前新增 <code>nsenter --mount=/proc/1/ns/mnt</code> 即可使此命令在全域 mount namespace 下執行。KernelSU 本身也使用了 <a href="https://github.com/tiann/KernelSU/blob/77056a710073d7a5f7ee38f9e77c9fd0b3256576/manager/app/src/main/java/me/weishu/kernelsu/ui/util/KsuCli.kt#L115" target="_blank" rel="noreferrer">這種方法</a></li></ol><h2 id="kernelsu-可以修改-hosts-嗎-我要怎麼使用-adaway" tabindex="-1">KernelSU 可以修改 Hosts 嗎？ 我要怎麼使用 AdAway？ <a class="header-anchor" href="#kernelsu-可以修改-hosts-嗎-我要怎麼使用-adaway" aria-label="Permalink to &quot;KernelSU 可以修改 Hosts 嗎？ 我要怎麼使用 AdAway？&quot;">​</a></h2><p>當然。但是 KernelSU 沒有內建的 Hosts 支持，您可以安裝 <a href="https://github.com/symbuzzer/systemless-hosts-KernelSU-module" target="_blank" rel="noreferrer">systemless-hosts</a> 來做到這一點。</p><h2 id="為什麼全新安裝後模組不工作" tabindex="-1">為什麼全新安裝後模組不工作？ <a class="header-anchor" href="#為什麼全新安裝後模組不工作" aria-label="Permalink to &quot;為什麼全新安裝後模組不工作？&quot;">​</a></h2><p>如果您的模組需要修改 <code>/system</code> 檔案，您需要安裝 <a href="./metamodule.html">metamodule</a> 來掛載 <code>system</code> 目錄。其他模組功能(腳本、sepolicy、system.prop)無需 metamodule 即可運作。</p><p><strong>解決方案</strong>：參閱 <a href="./metamodule.html">Metamodule 指南</a> 獲取安裝說明。</p><h2 id="什麼是-metamodule-為什麼需要它" tabindex="-1">什麼是 metamodule，為什麼需要它？ <a class="header-anchor" href="#什麼是-metamodule-為什麼需要它" aria-label="Permalink to &quot;什麼是 metamodule，為什麼需要它？&quot;">​</a></h2><p>Metamodule 是一個特殊模組，為掛載常規模組提供基礎架構。請參閱 <a href="./metamodule.html">Metamodule 指南</a> 獲取完整說明。</p>',40)])])}const c=a(t,[["render",n]]);export{k as __pageData,c as default};
